import sys
from collections import defaultdict

# Read input
n, m = map(int, sys.stdin.readline().split())
edges = [list(map(int, sys.stdin.readline().split())) for _ in range(m)]

# Create a graph representation
graph = defaultdict(list)
for a, b in edges:
    graph[a].append(b)
    graph[b].append(a)

# Initialize the list to store the final cables
final_cables = []

# Function to add a cable in both directions
def add_cable(u, v):
    final_cables.append((u, v))
    final_cables.append((v, u))

# Process each computer
for i in range(1, n + 1):
    # Count the directions of cables coming out of computer i
    out_directions = defaultdict(int)
    for neighbor in graph[i]:
        for next_neighbor in graph[neighbor]:
            if next_neighbor != i:
                out_directions[next_neighbor] += 1

    # Try to group cables into pairs
    for neighbor in graph[i]:
        if out_directions[neighbor] == 0:
            add_cable(i, neighbor)
        else:
            for next_neighbor in graph[neighbor]:
                if next_neighbor != i and out_directions[next_neighbor] == 0:
                    add_cable(neighbor, next_neighbor)
                    out_directions[next_neighbor] = 1

# Output the result
print(len(final_cables))
for u, v in final_cables:
    print(u, v)
